JOIN public.courses c ON c.slug = 'full-stack-web-developer-with-ai-and-ml-integration'
LEFT JOIN public.course_modules m ON m.course_id = c.id AND m.title = v.module_title
ON CONFLICT (course_id, url) DO NOTHING;
